zsh_status_variable.script:
status=0
./dist/jlog events.jsonl > report.txt || status=$?
case "$status" in
  0) echo 'All records are valid.' ;;
  4) echo 'Malformed records found; see report.txt.' ;;
  *) echo "jlog failed with exit $status" >&2 ;;
esac

